INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65444901', 65444901, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'KANTOR PUSAT DIREKTORAT JENDERAL PERHUBUNGAN UDARA', 'Pengembangan dan Pemeliharaan Aplikasi Database Perizinan Terintegrasi dengan OSS pada Modul Layanan Pengelolaan Perizinan Usaha dan Kegiatan Angkutan Udara, Layanan Pengelolaan Penempatan dan Perubahanan Catatan Perwakilan Perusahaan Angkutan Udara Asing di Indonesia Pada Portal DJPU', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 398135000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 Paket', 'Pengembangan dan Pemeliharaan Aplikasi Database Perizinan Terintegrasi dengan OSS pada Modul Layanan Pengelolaan Perizinan Usaha dan Kegiatan Angkutan Udara, Layanan Pengelolaan Penempatan dan Perubahanan Catatan Perwakilan Perusahaan Angkutan Udara Asing di Indonesia Pada Portal DJPU', 'NO MODUL KETERANGAN 1 Modul Rencana Bisnis Pengembangan dan Pemeliharaan Modul yang digunakan oleh calon pelaku usaha untuk menginputkan data rencana bisnis perusahaan yang terdiri dari SDM, armada, rute penerbangan, biaya, crew, dan data rencana bisnis lainnya. 2 Modul Pendaftaran Sertifikat Standar Pengembangan dan Pemeliharaan - Modul yang dapat digunakan untuk menginputkan permohoanan sertifikat standar - Dapat digunakan untuk mengunggah/ melampirkan dokumen administrasi perusahaan (persyaratan) - dapat digunakan untuk mengunggah/ melampirkan dokumen data dukung permohonan - dapat digunakan untuk melakukan monitoring posisi dan status permohonan 3 Modul Pendaftaran Asuransi Tanggung Jawab Pengangkut Pengembangan dan Pemeliharaan - Modul yang dapat digunakan untuk menginputkan pelaporan asuransi tanggungjawab pengangkut - Modul yang dapat digunakan untuk menginputkan permohonan perubahan/perpanjangan asuransi tanggungjawab pengangkut 4 Modul Pembayaran PNBP Pengembangan dan Pemeliharaan - Modul yang dapat digunakan oleh pelaku usaha untuk membuat tagihan secara mandiri - Dapat terintegrasi dengan SIMPONI - Dapat digunakan untuk melakukan monitoring status pembayaran 5 Modul Verifikasi dan Evaluasi Rencana Bisnis Pengembangan dan Pemeliharaan Modul yang dapat digunakan oleh inspektur untuk melakukan verifikasi dan evaluasi rencana bisnis yang diajukan oleh pelaku usaha. 6 Modul Verifikasi dan Evaluasi Permohonan Sertifikat Standar Pengembangan dan Pemeliharaan - Modul yang digunakan untuk melakukan verifikasi dan evaluasi permohonan sertifikat standar. - Dapat digunakan oleh kepala seksi untuk melakukan disposisi dan penunjukan personel - Dapat digunakan untuk melakukan verifikasi dan evaluasi permohonan oleh staff (checklist evaluasi) - Dapat digunakan untuk mengunggah dokumen telaah staff/ rekomendasi pemberian persetujuan - Dapat digunakan untuk memberikan persetujuan secara berjenjang mulai dari Kasi, Kasubdit, Direktur, dan Dirjen - Terintegrasi dengan OSS RBA untuk mengupdate status verifikasi dan persetujuan 7 Modul Verifikasi Asuransi Tanggung Jawab Pengangkut Pengembangan dan Pemeliharaan Modul yang digunakan oleh petugas verifikator untuk melakukan verifikasi pelaporan asuransi tanggung jawab pengangkut dan permohonan perubahan serta pepanjangan asuransi tanggung jawab pengangkut 8 Modul Verifikasi Pembayaran Pengembangan dan Pemeliharaan Modul yang dapat digunakan oleh inspektur untuk melakukan verifikasi data pembayaran. 9 Modul Pendaftaran Akun dan Perusahaan Pengembangan dan Pemeliharaan - Modul yang digunakan untuk melakukan Pendaftaran akun perusahaan. - Terintegrasi dengan OSS RBA untuk mengambil data perusahaan. - Mampu digunakan untuk melakukan Update dan melengkapi data profile perusahaan 10 Modul Verifikasi Data Akun Pengembangan dan Pemeliharaan Modul yang digunakan oleh Inspektur untuk melakukan verifikasi data akun pengguna dan data perusahaan 11 Modul Laporan Pengembangan dan Pemeliharaan Modul yang digunakan untuk menyajikan rekapitulasi permohonan Sertifikat Standar dan rekapitulasi pembayaran. 12 Modul Pengaturan Aplikasi Pengembangan dan Pemeliharaan Modul yang digunakan untuk melakukan pengaturan aplikasi dan mengelola data master.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2132676);
