INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65409173', 65409173, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Perancangan Rencana Konten dan Publikasi SDI', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 118800000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Melakukan riset tren dan topik terbaru untuk ide konten kreatif yang relevan, serta mendukung inisiatif penyebarluasan informasi kebijakan Satu Data Indonesia; Mengembangkan strategi konten media sosial dan menyusun kalender konten bulanan untuk meningkatkan pemahaman publik tentang Satu Data Indonesia dan menyampaikan pesan secara terstruktur; Menyusun panduan komunikasi dan memastikan konsistensi brand voice di seluruh konten, serta mengawasi interaksi publik di media sosial dan menanggapi pertanyaan atau umpan balik; Mengembangkan konten edukatif dan multimedia, serta merancang kampanye tematik untuk mendukung narasi Satu Data Indonesia, memperkuat transparansi, dan keterbukaan data; Mengembangkan booklet, pedoman, dan publikasi cetak lainnya, serta mengelola proses penyuntingan dan produksi untuk memastikan penyampaian informasi Satu Data Indonesia secara efektif;', 'Rencana kerja untuk strategi konten media sosial dan kalender konten bulanan disusun guna meningkatkan pemahaman publik tentang Satu Data Indonesia. Konten informatif dan edukatif, termasuk konten multimedia, yang ditulis dan disesuaikan dengan panduan bahasa yang komunikatif, serta yang dikembangkan bersama tim kreatif untuk dipublikasikan di berbagai platform media sosial. Artikel yang dikelola dan disunting untuk publikasi di media cetak dan online. Booklet, pedoman, dan publikasi cetak lainnya yang dikembangkan untuk menyampaikan informasi secara efektif kepada publik. Koordinasi dengan media dilakukan untuk meningkatkan eksposur Satu Data Indonesia. Laporan performa konten media sosial yang dianalisis untuk meningkatkan jangkauan dan keterlibatan audiens. Laporan bulanan Tenaga Ahli Perencanaan Konten dan Publikasi Satu Data Indonesia Tahun Anggaran 2026 memuat rekam pelaksanaan pekerjaan setiap bulannya dalam rangka mencapai keluaran sebagaimana pada nomor 1 sampai dengan nomor 6; Laporan Akhir pelaksanaan kontrak Tenaga Ahli Perencanaan Konten dan Publikasi Kinerja Satu Data Indonesia Tahun Anggaran 2026 memuat keluaran sebagaimana pada nomor 1 sampai dengan nomor 6;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2134021);
