INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65447737', 65447737, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pemenuhan Prioritas Direktif Presiden Pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 2242298000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1.0 PAKET', 'Pemenuhan Prioritas Direktif Presiden pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026 yang bertujuan untuk memastikan pelaksanaan program dan kebijakan strategis Presiden dapat terlaksana secara efektif dan tepat sasaran, mendukung pencapaian target kinerja kementerian, serta meningkatkan efektivitas pengawasan dan akuntabilitas internal. Ruang lingkup pekerjaan meliputi perencanaan, koordinasi, pelaksanaan, monitoring, dan evaluasi kegiatan yang terkait dengan prioritas Direktif Presiden, termasuk penyediaan sumber daya, dokumen, dan pelaporan yang diperlukan, serta pemenuhan seluruh persyaratan administrasi dan teknis sesuai ketentuan peraturan perundang-undangan yang berlaku, yang dilaksanakan dalam 1 paket pekerjaan selama 1 Tahun Anggaran 2026.', 'Pemenuhan Prioritas Direktif Presiden pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026, yang mencakup perencanaan, koordinasi, pelaksanaan, monitoring, evaluasi, dan pelaporan program sesuai arahan Presiden serta target kinerja kementerian. Lingkup pekerjaan mencakup penyusunan rencana kerja tahunan yang selaras dengan prioritas Direktif Presiden, pelaksanaan kegiatan teknis dan administratif terkait program prioritas, pemantauan dan evaluasi pelaksanaan kegiatan untuk memastikan efektivitas dan akuntabilitas, serta penyusunan laporan kegiatan yang lengkap, akurat, dan tepat waktu sesuai ketentuan peraturan perundang-undangan. Pekerjaan harus dilaksanakan sesuai prinsip akuntabilitas, transparansi, efisiensi, dan efektivitas, terdokumentasi dengan baik, mematuhi standar administrasi pemerintah, serta siap diaudit oleh pihak berwenang, dengan hasil akhir berupa laporan pelaksanaan kegiatan yang komprehensif, rencana kerja tahunan yang disetujui, dan bukti pelaksanaan seluruh kegiatan prioritas, dilaksanakan dalam 1 paket pekerjaan selama 1 Tahun Anggaran 2026.', 2242298000, 'high', 'Uraian pekerjaan sangat umum dan menyerupai fungsi inti internal Inspektorat Jenderal seperti perencanaan, koordinasi, monitoring, evaluasi, dan pelaporan. Pengadaan jasa eksternal untuk tugas pengawasan dan akuntabilitas internal berindikasi tidak relevan serta berpotensi menjadi belanja pendampingan yang semestinya dilaksanakan oleh unit internal. Nilai paket yang besar dengan spesifikasi generik memperkuat indikasi pemborosan.', NULL, NULL, 3, 1, 1, 1, 1, 2134461);
