INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65446411', 65446411, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'KANTOR PUSAT DIREKTORAT JENDERAL PERHUBUNGAN UDARA', 'Pengembangan dan Pemeliharaan Aplikasi Perizinan Direktorat Angkutan Udara pada Modul Layanan Pemetaan Jaringan dan Rute Penerbangan, Layanan Persetujuan Terbang angkutan Udara Dalam Negeri dan Luar Negeri Pada Portal DJPU', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 398135000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1 Paket', 'Pengembangan dan Pemeliharaan Aplikasi Perizinan Direktorat Angkutan Udara pada Modul Layanan Pemetaan Jaringan dan Rute Penerbangan, Layanan Persetujuan Terbang angkutan Udara Dalam Negeri dan Luar Negeri Pada Portal DJPU', 'NO MODUL KETERANGAN 1 Modul Flight Approval Pengembangan dan Pemeliharaan: - Modul yang dapat digunakan untuk menginputkan pendaftaran flight approval untuk angkutan udara niaga berjadwal, baik domestik maupun internasional secara online. - Modul yang dapat digunakan untuk menginputkan pendaftaran flight approval untuk angkutan udara niaga tidak berjadwal, baik domestik maupun internasional secara online. - Modul yang dapat digunakan untuk menginputkan pendaftaran flight approval untuk angkutan udara non niaga, baik domestik maupun internasional secara online. 2 Modul Penetapan Pelaksanaan Rute Penerbangan (PPRP) Pengembangan dan Pemeliharaan: - Modul yang dapat digunakan untuk melakukan permohonan PPRP baru, perpanjangan, Perubahan, Pencabutan dan Pengembalian PPRP Dalam Negeri - Modul yang dapat digunakan untuk melakukan permohonan PPRP baru, perpanjangan, Perubahan, Pencabutan dan Pengembalian PPRP Luar Negeri 3 Modul Izin Overflying Pengembangan dan Pemeliharaan Modul yang dapat digunakan untuk melakukan permohonan Izin Overflying baru 4 Modul Codeshare Pengembangan dan Pemeliharaan: - Modul yang dapat digunakan untuk melakukan permohonan codeshare baru dan perubahan codeshare dalam negeri. - Modul yang dapat digunakan untuk melakukan permohonan codeshare baru dan perubahan codeshare dalam negeri. 5 Modul Pembayaran PNBP Pengembangan dan Pemeliharaan: - Modul yang dapat digunakan untuk melakukan pembuatan tagihan pembayaran flight approval dan PPRP yang terintegrasi dengan SIMPONI - Modul yang dapat digunakan untuk menampilkan atau memonitoring tagihan yang menunggu untuk dibayarkan, pembayaran gagal dan pembayaran berhasil. 6 Modul Slot Time Pengembangan dan Pemeliharaan Modul yang dapat digunakan untuk monitoring atau menampilkan data slot time IASM. Modul yang dapat digunakan untuk monitoring atau menampilkan data slot time Chronos. 7 Modul Verifikasi dan Persetujuan Flight Approval Pengembangan dan Pemeliharaan Modul yang berguna untuk melakukan verifikasi dan evaluasi berjenjang terhadap permohonan flight approval 8 Modul Verifikasi dan Persetujuan PPRP Pengembangan dan Pemeliharaan Modul yang berguna untuk melakukan verifikasi dan evaluasi berjenjang terhadap permohonan PPRP 9 Modul Verifikasi dan Persetujuan Penerbangan Codeshare Pengembangan dan Pemeliharaan Modul yang berguna untuk melakukan verifikasi dan persetujuan berjenjang terhadap permohonan Codeshare hingga penerbitan surat penetapan codeshare. 10 Modul Verifikasi dan Persetujuan NAC Pengembangan dan Pemeliharaan Modul yang berguna untuk melakukan verifikasi dan evaluasi terhadap pelaporan data NAC 11 Modul Laporan Pengembangan dan Pemeliharaan Modul yang digunakan untuk menyajikan statistic permohonan FA, statistik permohonan PPRP, SLA FA, SLA PPRP, penggunaan slot time, rekapitulasi pembayaran dan log pengguna 12 Modul Pengaturan Aplikasi Pengembangan dan Pemeliharaan Modul yang digunakan untuk melakukan pengaturan aplikasi dan pengelolaan data master 13 Modul SIUAU Pengembangan dan Pemeliharaan Modul yang digunakan untuk mengelola data dan mencatat lampiran SIUAU dan lampiran diluar SIUAU milik Airlines..', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2135424);
