INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65409534', 65409534, 'analyze_legacy', 'Kab. Rokan Hulu', 'kabkota', 'Dinas Kesehatan', 'Belanja Pemeliharaan  Alat Kantor dan Rumah Tangga - Alat Rumah Tangga - Alat Pembersih ( Peralatan Kebersihan dan Bahan Pembersih)', 'Barang', 'Penunjukan Langsung', 'Riau, Rokan Hulu (Kab.)', 180000000, 'January 2026', 'BLUD', 1, 1, '1 Paket', '"Pengadaan bahan dan peralatan kebersihan untuk pemeliharaan rutin sanitasi RSUD Rokan Hulu. Lingkup barang meliputi: 1. Bahan Kimia: Pembersih lantai (Floor Cleaner), Karbol Wangi, Pembersih Kaca, dan Desinfektan. 2. Peralatan Manual: Sapu ijuk/lidi, Kain pel (mop set), Sikat lantai, Ember, dan Gayung. 3. Perlengkapan Sampah: Plastik sampah (Trashbag) Hitam & Kuning Medis. 4. Spesifikasi mengacu pada standar higiene rumah sakit."', 'Penyedia wajib menawarkan barang dengan ketentuan: 1. Izin Edar (PKD): Seluruh bahan kimia pembersih (cairan lantai, disinfektan, sabun) wajib memiliki Nomor Izin Edar PKD (Perbekalan Kesehatan Dalam Negeri) dari Kemenkes RI yang masih berlaku. 2. Keamanan (MSDS): Menyertakan Material Safety Data Sheet (MSDS) untuk produk bahan kimia berbahaya sebagai acuan penanganan K3RS. 3. TKDN: Memprioritaskan produk dalam negeri dengan nilai TKDN + BMP minimal 40% (sesuai etalase E-Katalog). 4. Kemasan: Barang dikirim dalam kemasan asli pabrik, segel utuh, tidak bocor, dan memiliki label yang jelas (Nama Produk, Batch No, Expired Date).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2136336);
