INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65410037', 65410037, 'analyze_legacy', 'Kab. Rokan Hulu', 'kabkota', 'Dinas Kesehatan', 'Belanja Kawat/Faksimili/Internet/TV Berlangganan - Internet RSUD', 'Jasa Lainnya', 'Penunjukan Langsung', 'Riau, Rokan Hulu (Kab.)', 72000000, 'January 2026', 'BLUD', 1, 1, '1 Paket', '"Jasa Sewa Bandwidth Internet Utama (Dedicated) dan Internet Cadangan (Backup Link) untuk menjamin kontinuitas pelayanan SIMRS (High Availability). Termasuk manajemen bandwidth dan keamanan jaringan."', 'Mengingat RSUD Rokan Hulu sedang gencar digitalisasi (RME/Simrs), spesifikasi teknis internet tidak boleh sembarangan. Berikut poin kuncinya: 1. Dedicated Connection (Rasio 1:1): 2. Wajib untuk Server SIMRS. Kecepatan Upload dan Download harus sama (Simetris). Jangan pakai Broadband (Indihome biasa) untuk server, karena uploadnya kecil. 3. IP Public Static: Wajib ada minimal 1-5 IP Public. Ini digunakan agar Server SIMRS bisa diakses dari luar (untuk bridging BPJS/SatuSehat dan akses dokter dari rumah). 4. Service Level Agreement (SLA): 5. Minimal 99% - 99.5%. Artinya dalam sebulan, internet boleh mati maksimal hanya 3-7 jam. Jika lebih dari itu, Provider wajib memberikan Restitusi (potongan tagihan). 6. Multi-Router Traffic Grapher (MRTG): 7. Penyedia wajib memberikan akses grafik pemakaian bandwidth agar RSUD bisa memantau apakah speed yang dikirim sesuai kontrak atau tidak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2137730);
